BEGIN;
CREATE TABLE IF NOT EXISTS mission_bridge_ethics_salons(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,title TEXT NOT NULL,session_number INTEGER NOT NULL CHECK(session_number BETWEEN 1 AND 8),starts_at TIMESTAMPTZ,capacity INTEGER NOT NULL DEFAULT 20,status TEXT NOT NULL DEFAULT 'planned',created_by TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mission_bridge_salon_registrations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,salon_id UUID NOT NULL REFERENCES mission_bridge_ethics_salons(id),user_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'registered',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(salon_id,user_id));
CREATE TABLE IF NOT EXISTS mission_bridge_discussion_viewpoints(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,session_number INTEGER NOT NULL CHECK(session_number BETWEEN 1 AND 8),position TEXT NOT NULL CHECK(position IN('supporting','opposing','nuanced')),claim TEXT NOT NULL,evidence_type TEXT NOT NULL CHECK(evidence_type IN('empirical','philosophical','historical','theological')),source_content_id UUID REFERENCES mission_bridge_content_catalog(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_anonymous_questions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,session_number INTEGER NOT NULL CHECK(session_number BETWEEN 1 AND 8),user_id_hash TEXT NOT NULL,question TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'submitted',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_discussion_minutes(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,salon_id UUID REFERENCES mission_bridge_ethics_salons(id),facilitator_user_id TEXT NOT NULL,summary TEXT NOT NULL,agreements JSONB NOT NULL DEFAULT '[]'::jsonb,disagreements JSONB NOT NULL DEFAULT '[]'::jsonb,source_refs JSONB NOT NULL DEFAULT '[]'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_followup_invitations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,invitation_type TEXT NOT NULL CHECK(invitation_type IN('further_reading','one_to_one','gospel_core_course')),participant_requested BOOLEAN NOT NULL DEFAULT FALSE,status TEXT NOT NULL DEFAULT 'draft',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(participant_requested=TRUE));
CREATE TABLE IF NOT EXISTS mission_bridge_viewpoint_learning(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,session_number INTEGER NOT NULL,understanding_before INTEGER CHECK(understanding_before BETWEEN 1 AND 5),understanding_after INTEGER CHECK(understanding_after BETWEEN 1 AND 5),question_asked BOOLEAN NOT NULL DEFAULT FALSE,completed BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_ethics_salons','mission_bridge_salon_registrations','mission_bridge_discussion_viewpoints','mission_bridge_anonymous_questions','mission_bridge_discussion_minutes','mission_bridge_followup_invitations','mission_bridge_viewpoint_learning'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
UPDATE mission_bridge_program_definitions SET title='AI时代的人、意义与信仰探索',active_version='2.0.0' WHERE id='ai-faith-dialogue-8';
INSERT INTO mission_bridge_program_versions(program_id,version,definition,safeguarding_profile) VALUES('ai-faith-dialogue-8','2.0.0','{"durationWeeks":8,"sessionMode":"hybrid","voluntary":true,"steps":8,"sessions":["AI能否理解，还是只是在预测？","人的价值是否来自生产力？","意识、自由意志和责任","科技进步为何没有消除焦虑","道德能否只由社会共识产生","苦难是否推翻上帝存在","耶稣是宗教教师还是历史中的主","信仰、理性和个人回应"],"features":["技术伦理沙龙报名","阅读材料","正反观点","匿名提问","主持人指南","讨论纪要","一对一后续邀请"],"metrics":["深度讨论完成率","主动提问率","不同观点理解提升","主动请求进一步阅读或对谈比例"],"excludedMetric":"决志数量"}'::jsonb,'{"fairOpposingViews":true,"noInventedConsensus":true,"distinguishPhilosophyAndEvidence":true,"citationsRequired":true,"noFaithStatusInference":true,"professionalReferral":true,"noCoercion":true}'::jsonb) ON CONFLICT DO NOTHING;
COMMIT;
